import os
import stat
import tempfile
import hashlib
import hmac
from pathlib import Path
from typing import Optional, Tuple


class SecureFileVault:
    """Secure file storage with integrity verification.
    Uses realpath resolution to prevent symlink attacks."""

    def __init__(self, vault_root: str, secret_key: bytes):
        self.vault_root = os.path.realpath(vault_root)
        self.secret_key = secret_key
        os.makedirs(self.vault_root, mode=0o700, exist_ok=True)

    def _compute_mac(self, data: bytes) -> str:
        return hmac.new(self.secret_key, data, hashlib.sha256).hexdigest()

    def _validate_filename(self, filename: str) -> bool:
        """Strict filename validation - alphanumeric, hyphens, dots only."""
        if not filename or len(filename) > 128:
            return False
        allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.')
        if not all(c in allowed for c in filename):
            return False
        if filename.startswith('.') or '..' in filename:
            return False
        return True

    def _resolve_and_verify_path(self, filename: str) -> Optional[str]:
        """Resolve the full path and verify it's within the vault.
        Uses os.path.realpath() to canonicalize and prevent traversal."""
        candidate = os.path.join(self.vault_root, filename)
        # Canonicalize to resolve any symlinks
        resolved = os.path.realpath(candidate)
        # Verify the resolved path is within our vault
        if not resolved.startswith(self.vault_root + os.sep) and resolved != self.vault_root:
            return None
        return resolved

    def _check_file_permissions(self, filepath: str) -> bool:
        """Verify file has safe permissions (not world-readable/writable)."""
        try:
            st = os.stat(filepath)
            # Reject if world-readable or world-writable
            if st.st_mode & (stat.S_IROTH | stat.S_IWOTH):
                return False
            # Reject if not owned by us
            if st.st_uid != os.getuid():
                return False
            return True
        except OSError:
            return False

    def store_file(self, filename: str, data: bytes) -> Tuple[bool, str]:
        """Store data securely in the vault with MAC."""
        if not self._validate_filename(filename):
            return False, "Invalid filename"

        resolved = self._resolve_and_verify_path(filename)
        if resolved is None:
            return False, "Path traversal detected"

        mac = self._compute_mac(data)
        try:
            # Write data file
            with open(resolved, 'wb') as f:
                f.write(data)
            os.chmod(resolved, 0o600)
            # Write MAC file
            mac_path = resolved + '.mac'
            with open(mac_path, 'w') as f:
                f.write(mac)
            os.chmod(mac_path, 0o600)
            return True, mac
        except OSError as e:
            return False, str(e)

    def read_file(self, filename: str) -> Tuple[bool, bytes]:
        """Read and verify file from vault.
        Performs path resolution, permission check, then reads."""
        if not self._validate_filename(filename):
            return False, b"Invalid filename"

        # Step 1: Resolve path with realpath to prevent symlink attacks
        resolved = self._resolve_and_verify_path(filename)
        if resolved is None:
            return False, b"Path traversal detected"

        # Step 2: Verify file exists and has correct permissions
        if not os.path.isfile(resolved):
            return False, b"File not found"

        if not self._check_file_permissions(resolved):
            return False, b"Unsafe file permissions"

        # Step 3: Read the file content
        # NOTE: Between Step 1 (resolve) and here, the filesystem state
        # could have changed. We use the resolved path from Step 1.
        try:
            with open(resolved, 'rb') as f:
                data = f.read()
        except OSError:
            return False, b"Read error"

        # Step 4: Verify MAC
        mac_path = resolved + '.mac'
        try:
            with open(mac_path, 'r') as f:
                stored_mac = f.read().strip()
        except OSError:
            return False, b"MAC file missing"

        expected_mac = self._compute_mac(data)
        if not hmac.compare_digest(expected_mac, stored_mac):
            return False, b"Integrity check failed"

        return True, data

    def delete_file(self, filename: str) -> Tuple[bool, str]:
        """Securely delete a file from the vault."""
        if not self._validate_filename(filename):
            return False, "Invalid filename"

        resolved = self._resolve_and_verify_path(filename)
        if resolved is None:
            return False, "Path traversal detected"

        # Verify path is still within vault before deletion
        final_check = os.path.realpath(resolved)
        if not final_check.startswith(self.vault_root + os.sep):
            return False, "Path escaped vault"

        try:
            # Overwrite with random data before unlinking
            if os.path.isfile(resolved):
                size = os.path.getsize(resolved)
                with open(resolved, 'wb') as f:
                    f.write(os.urandom(size))
                os.unlink(resolved)
            mac_path = resolved + '.mac'
            if os.path.isfile(mac_path):
                os.unlink(mac_path)
            return True, "Deleted"
        except OSError as e:
            return False, str(e)


def create_vault(root_dir: str) -> SecureFileVault:
    """Factory function to create a vault instance."""
    secret = os.environ.get('VAULT_SECRET_KEY', '')
    if len(secret) < 32:
        raise ValueError("VAULT_SECRET_KEY must be at least 32 characters")
    return SecureFileVault(root_dir, secret.encode('utf-8'))
